def semver_cmp(a: str, b: str) -> int:
    def parse_version(v: str) -> list:
        parts = []
        for part in v.split('.'):
            try:
                parts.append(int(part))
            except ValueError:
                parts.append(part)
        return parts

    def compare_parts(a_parts: list, b_parts: list) -> int:
        for i in range(max(len(a_parts), len(b_parts))):
            a_val = a_parts[i] if i < len(a_parts) else 0
            b_val = b_parts[i] if i < len(b_parts) else 0

            if isinstance(a_val, int) and isinstance(b_val, int):
                if a_val < b_val:
                    return -1
                elif a_val > b_val:
                    return 1
            elif isinstance(a_val, int):
                return 1
            elif isinstance(b_val, int):
                return -1
            else:
                if a_val < b_val:
                    return -1
                elif a_val > b_val:
                    return 1
        return 0

    a_parts = parse_version(a)
    b_parts = parse_version(b)
    return compare_parts(a_parts, b_parts)


